import * as T from 'three';
export function createVehicle(scene,x,z,ambulance=false){
const root=new T.Group();root.position.set(x,.1,z);scene.add(root);root.name=ambulance?'救護車':'消防車';const lights=[];
const paint=new T.MeshStandardMaterial({color:ambulance?'#f0f2ef':'#b92120',metalness:.42,roughness:.26});const white=new T.MeshStandardMaterial({color:'#eceddf',metalness:.2,roughness:.35}),orange=new T.MeshStandardMaterial({color:'#f06b20',roughness:.4}),metal=new T.MeshStandardMaterial({color:'#8e9ea4',metalness:.8,roughness:.32}),dark=new T.MeshStandardMaterial({color:'#172027',roughness:.82}),glass=new T.MeshPhysicalMaterial({color:'#254658',metalness:.45,roughness:.13,clearcoat:1}),red=new T.MeshStandardMaterial({color:'#a51416',emissive:'#ff2315',emissiveIntensity:2});
function box(w,h,d,x,y,z,m,bevel=0){let geo;if(bevel){const s=new T.Shape();s.moveTo(-w/2,-h/2);s.lineTo(w/2,-h/2);s.lineTo(w/2,h/2);s.lineTo(-w/2,h/2);s.closePath();geo=new T.ExtrudeGeometry(s,{depth:d-2*bevel,bevelEnabled:true,bevelThickness:bevel,bevelSize:bevel,bevelSegments:2,steps:1});geo.translate(0,0,-d/2+bevel)}else geo=new T.BoxGeometry(w,h,d);const o=new T.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;root.add(o);return o}
function cyl(r,len,x,y,z,m){const o=new T.Mesh(new T.CylinderGeometry(r,r,len,20),m);o.rotation.z=Math.PI/2;o.position.set(x,y,z);o.castShadow=true;root.add(o);return o}
function decal(text,w,h,x,y,z,ry,color='#ffffff',bg=null){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');if(bg){ctx.fillStyle=bg;ctx.fillRect(0,0,512,128)}ctx.fillStyle=color;ctx.font='bold 58px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,256,64);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const o=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false}));o.position.set(x,y,z);o.rotation.y=ry;root.add(o)}
box(1.85,.23,4.85,0,.45,0,dark,.04);
if(ambulance){box(2.02,1.9,3.45,0,1.64,.65,paint,.09);box(1.97,1.32,1.35,0,1.37,-1.7,paint,.09);box(1.92,.5,1.02,0,2.02,-1.48,paint,.07);box(1.86,.48,.8,0,1.01,-2.12,paint,.07);box(1.65,.71,.04,0,1.87,-2.01,glass).rotation.x=-.18;box(1.96,.16,2.65,0,2.67,.7,white,.06);box(.8,.14,1.1,0,2.8,.7,metal,.03);
}else{box(2.1,1.48,2.92,0,1.32,.92,paint,.055);box(2.06,1.94,1.82,0,1.52,-1.62,paint,.075);box(1.82,.79,.035,0,2.03,-2.58,glass);box(.055,.86,.045,0,2.03,-2.62,dark);box(2.07,.1,1.8,0,2.54,-1.62,paint,.025);}
const nose=ambulance?-2.58:-2.62;box(1.98,.18,.2,0,.7,nose,metal,.025);box(.93,.45,.04,0,1.17,nose-.015,dark);for(let k=0;k<5;k++)box(.87,.032,.05,0,1.01+k*.078,nose-.05,metal);decal('119',.48,.17,0,.68,nose-.12,Math.PI,'#253344','#e9e4d1');
for(const side of [-1,1]){const sx=side*(ambulance?1.06:1.09);for(const zz of [-1.63,1.56]){cyl(.47,.25,sx,.56,zz,dark);cyl(.29,.27,sx+side*.025,.56,zz,metal);cyl(.14,.29,sx+side*.035,.56,zz,dark);for(let n=0;n<6;n++){const a=n*Math.PI/3;cyl(.031,.3,sx+side*.04,.56+Math.cos(a)*.21,zz+Math.sin(a)*.21,white)}}
box(.035,.72,1.14,sx,2.02,-1.6,glass);box(.025,.055,1.17,sx,1.62,-1.6,metal);box(.045,.045,.26,sx,1.46,-1.19,metal);box(.08,.055,.42,sx,1.98,-2.15,dark);box(.2,.33,.15,sx+side*.14,1.98,-2.25,dark,.025);box(.09,.35,.04,sx+side*.22,1.99,-2.33,metal);box(.18,.1,.95,sx,.71,-1.55,metal);
const head=new T.MeshStandardMaterial({color:'#ffeccb',emissive:'#ffedc9',emissiveIntensity:.7});box(.4,.27,.08,side*.75,1.12,nose-.04,head,.025);box(.16,.13,.09,side*.96,1.48,nose,orange,.015);
if(ambulance){box(.025,.28,3.1,sx,1.37,.6,orange);box(.028,.065,3.1,sx,1.62,.6,white);box(.04,.76,1.22,sx,2.06,.13,glass);box(.028,1.64,.025,sx,1.58,-.54,metal);box(.028,.06,.36,sx,1.55,.61,metal);decal('救護車',1.6,.38,sx+side*.025,1.9,1.62,side*Math.PI/2,'#234269');decal('AMBULANCE',2.6,.25,sx+side*.027,1.02,.6,side*Math.PI/2,'#d55a20');for(let a=0;a<3;a++){const bar=box(.035,.12,.63,sx+side*.04,2.3,1.57, new T.MeshStandardMaterial({color:'#2065a3'}));bar.rotation.x=a*Math.PI/3}
}else{for(let k=0;k<3;k++){const zz=-.08+k*.94;box(.035,1.14,.8,sx,1.48,zz,metal);for(let n=0;n<11;n++)box(.045,.018,.78,sx+side*.008,.99+n*.093,zz,dark);box(.06,.055,.25,sx+side*.03,1.04,zz,white)}box(.038,.14,3.05,sx,.81,.92,white);decal('消防 119',1.18,.28,sx+side*.025,1.42,-1.6,side*Math.PI/2);box(.04,.37,.5,sx,1.04,-.15,dark);for(let n=0;n<3;n++)cyl(.075,.07,sx+side*.04,1.15,-.31+n*.16,metal);}
// Front roof lamps and rear flush-mounted lamps have separate mounting heights.
const frontLamp=box(.36,.16,.3,side*.67,ambulance?2.79:2.69,-1.25,red.clone(),.025);lights.push(frontLamp);
const rearLampY=ambulance?2.42:1.91;
const rearHousing=box(.44,.24,.12,side*.67,rearLampY,2.49,dark,.01);rearHousing.name='後警示燈固定座';
const rearLamp=box(.34,.14,.08,side*.67,rearLampY,2.57,red.clone(),.01);rearLamp.name='後捲門警示燈';lights.push(rearLamp);}
if(!ambulance){for(const xx of [-.7,.7])box(.08,.08,2.85,xx,2.25,.92,metal);for(let k=0;k<12;k++)box(1.42,.055,.055,0,2.25,-.4+k*.24,metal);box(.5,.23,1.15,0,2.39,.9,dark,.03);for(let k=0;k<5;k++)box(.57,.04,1.2,0,2.31+k*.045,.9,white);}
const rear=2.46;box(2.02,.17,.2,0,.7,rear,metal,.02);if(ambulance){box(.045,1.65,.035,0,1.62,rear,dark);for(const xx of [-.5,.5])box(.7,.6,.03,xx,2.05,rear,glass);decal('救護車',1.4,.3,0,1.4,rear+.03,0,'#28568b');}else{box(1.73,1.17,.04,0,1.42,rear,metal);for(let k=0;k<10;k++)box(1.72,.024,.05,0,.92+k*.105,rear+.01,dark)}for(const xx of [-.92,.92]){box(.12,.35,.06,xx,1.1,rear+.03,red);box(.12,.12,.065,xx,.86,rear+.03,orange)}
return {root,lights};
}
